var t=[{title:`De aanpassingscyclus`,text:`Een training is een prikkel. Je spieren leveren kracht, je hart en bloedvaten leveren meer zuurstof en je oefent bewegingsvaardigheden. Direct daarna kan vermoeidheid je prestaties een tijdje verlagen. Tijdens het herstel dat volgt, herstelt je lichaam, vult het zijn voorraden aan en past het zich aan. Het resultaat merk je na weken en maanden van herhaalde cycli.`},{title:`Specifieke aanpassingen`,text:`Het SAID-principe (Specific Adaptation to Imposed Demands) betekent dat je lichaam zich vooral aanpast aan wat je oefent. Zware squats verbeteren de krachtlevering in squatachtige patronen, en stevig wandelen traint vooral het aerobe vermogen. Algemene fitheid combineert meerdere soorten uitdaging. Vroege krachtwinst komt vaak door betere coördinatie en rekrutering door het zenuwstelsel, terwijl merkbare spiergroei meestal langer duurt.`},{title:`Supercompensatie`,text:`Een bekend diagram toont fitheid die na training daalt, herstelt en dan kort boven het beginpunt uitkomt. Het is een nuttig lesplaatje, maar geen nauwkeurig tijdschema en geen universele biologische wet. Verschillende systemen herstellen in verschillend tempo, en je hoeft elke sessie niet af te stemmen op een mythische piek.`},{title:`Voorbeeld`,text:`Een beginner doet twee matige full-body-trainingen per week. Na een aantal sessies voelen dezelfde oefeningen makkelijker. Hij of zij voegt een of twee herhalingen, een beetje gewicht of een andere zorgvuldig gekozen uitdaging toe en houdt de techniek goed. Als hij of zij zware sessies blijft opstapelen zonder herstel, kan de vooruitgang stagneren.`},{title:`TrainUp gebruiken`,text:`Kies een hoofddoel in Profiel, vink je sets af tijdens elke training en beoordeel daarna je inspanning. Geschiedenis toont een grafiek van 4 weken, dus kijk naar trends over meerdere weken. Denk voordat je training zwaarder maakt aan je slaap, spierpijn en hoe consistent je bent geweest.`}];var a=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Beweegrichtlijnen van de WHO`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC9219310/`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};